// ============================================================
//  Matvilingo — ОДИН ФАЙЛ: сайт + реєстрація + сервер.
//  Нічого встановлювати не треба, тільки Node.js 16+ (nodejs.org).
//  Запуск:   node matvilingo.js
//  Відкрий:  http://localhost:3000
// ============================================================
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const PORT = process.env.PORT || 3000;
const DB_FILE = path.join(__dirname, 'matvilingo-data.json');

// ---- "база даних" у JSON-файлі ----
let db = { secret: crypto.randomBytes(32).toString('hex'), nextId: 1, users: {} };
try { db = JSON.parse(fs.readFileSync(DB_FILE, 'utf8')); } catch (e) {}
function save() {
  fs.writeFileSync(DB_FILE + '.tmp', JSON.stringify(db));
  fs.renameSync(DB_FILE + '.tmp', DB_FILE);
}
save();

// ---- паролі й токени ----
const hashPass = (pass, salt) => new Promise((res, rej) =>
  crypto.scrypt(pass, salt, 64, (e, k) => e ? rej(e) : res(k.toString('hex'))));
const b64u = s => Buffer.from(s).toString('base64url');
function sign(id) {
  const body = b64u(JSON.stringify({ id, exp: Date.now() + 30 * 864e5 }));
  const sig = crypto.createHmac('sha256', db.secret).update(body).digest('base64url');
  return body + '.' + sig;
}
function verify(tok) {
  try {
    const [body, sig] = String(tok).split('.');
    const good = crypto.createHmac('sha256', db.secret).update(body).digest('base64url');
    if (sig.length !== good.length || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(good))) return null;
    const p = JSON.parse(Buffer.from(body, 'base64url').toString());
    if (p.exp < Date.now()) return null;
    return Object.values(db.users).find(u => u.id === p.id) || null;
  } catch (e) { return null; }
}

// ---- обмеження спроб ----
const hits = new Map();
function limited(ip) {
  const now = Date.now(), a = (hits.get(ip) || []).filter(t => now - t < 15 * 60e3);
  a.push(now); hits.set(ip, a);
  return a.length > 30;
}

const emailOk = e => typeof e === 'string' && e.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);
const pub = u => ({ name: u.name, email: u.email });

function readBody(req) {
  return new Promise((res, rej) => {
    let s = '';
    req.on('data', c => { s += c; if (s.length > 200000) { rej(new Error('big')); req.destroy(); } });
    req.on('end', () => { try { res(s ? JSON.parse(s) : {}); } catch (e) { rej(e); } });
  });
}
function send(res, code, obj) {
  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(obj));
}

const server = http.createServer(async (req, res) => {
  const url = req.url.split('?')[0];
  if (req.method === 'GET' && (url === '/' || url === '/Matvilingo.html' || url === '/index.html')) {
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    return res.end(HTML);
  }
  if (!url.startsWith('/api/')) { res.writeHead(404); return res.end('Not found'); }

  try {
    const ip = req.socket.remoteAddress;
    const body = ['POST', 'PUT'].includes(req.method) ? await readBody(req) : {};
    const user = verify((req.headers.authorization || '').replace(/^Bearer /, ''));

    if (url === '/api/register' && req.method === 'POST') {
      if (limited(ip)) return send(res, 429, { error: 'Забагато спроб. Спробуй пізніше.' });
      const { name, email, password, data } = body;
      if (!emailOk(email)) return send(res, 400, { error: 'Невірна пошта.' });
      if (typeof password !== 'string' || password.length < 8 || password.length > 200)
        return send(res, 400, { error: 'Пароль має містити від 8 символів.' });
      const e = email.toLowerCase();
      if (db.users[e]) return send(res, 409, { error: 'Акаунт із такою поштою вже існує. Увійди.' });
      const salt = crypto.randomBytes(16).toString('hex');
      const u = { id: db.nextId++, email: e, name: String(name || 'Учень').slice(0, 60),
        salt, hash: await hashPass(password, salt), data: data || {}, created: Date.now() };
      db.users[e] = u; save();
      return send(res, 200, { token: sign(u.id), user: pub(u), data: u.data });
    }
    if (url === '/api/login' && req.method === 'POST') {
      if (limited(ip)) return send(res, 429, { error: 'Забагато спроб. Спробуй пізніше.' });
      const { email, password } = body;
      const u = emailOk(email) && db.users[email.toLowerCase()];
      let ok = false;
      if (u && typeof password === 'string') {
        const h = await hashPass(password, u.salt);
        ok = crypto.timingSafeEqual(Buffer.from(h), Buffer.from(u.hash));
      }
      if (!ok) return send(res, 401, { error: 'Невірна пошта або пароль.' });
      return send(res, 200, { token: sign(u.id), user: pub(u), data: u.data });
    }
    if (!user) return send(res, 401, { error: 'Потрібно увійти.' });
    if (url === '/api/me' && req.method === 'GET') return send(res, 200, { user: pub(user), data: user.data });
    if (url === '/api/progress' && req.method === 'PUT') { user.data = body; save(); return send(res, 200, { ok: true }); }
    if (url === '/api/me' && req.method === 'DELETE') { delete db.users[user.email]; save(); return send(res, 200, { ok: true }); }
    send(res, 404, { error: 'Не знайдено.' });
  } catch (e) { send(res, 400, { error: 'Некоректний запит.' }); }
});

server.listen(PORT, () => console.log('Matvilingo працює: http://localhost:' + PORT));

